      "mainEntity": [
        {
          "@type": "Question",
          "name": "What certifications and standards do you support?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS uses documented procedures that support secure handling and reporting. Service options may include NIST SP 800-88 Rev. 2 aligned sanitization, HIPAA-aware disposal practices, DoD 5220.22-M references, and chain of custody documentation for eligible Bakersfield projects."
          }
        },
        {
          "@type": "Question",
          "name": "Is pickup available in Bakersfield?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pickup is available for qualifying Bakersfield business and institutional volumes. Scheduling depends on equipment type, quantity, loading conditions, and service needs. Contact STS to discuss the inventory and determine whether pickup, consolidation, or another collection arrangement fits the project."
          }
        },
        {
          "@type": "Question",
          "name": "What happens to collected equipment?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Collected equipment is documented, transported, evaluated for reuse or material recovery, and managed through a downstream workflow. Data-bearing devices can be handled under a separate sanitization or physical destruction plan before recycling proceeds, helping Bakersfield organizations maintain visibility over final disposition."
          }
        },
        {
          "@type": "Question",
          "name": "How much does business electronics recycling cost?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pickup and recycling may be free for qualifying volumes and equipment types. Some materials, specialty logistics, or destruction requirements can affect project scope. STS reviews the inventory before confirming the service plan and any applicable handling requirements for Bakersfield and Kern County organizations."
          }
        }
      ]
